CREATE function [dbo].[uspGetItemAvgRateDate] (@StoreId int,@ItemId  int,@Date datetime,@ByDate bit) returns nvarchar(50) as Begin Declare @Amount decimal(18,2);set @Amount =0;Declare @Qty decimal(18,2);set @Qty =0;Declare @AvgDate nvarchar(50);set @AvgDate =0;if @ByDate = 0 begin select @AvgDate = (select distinct avgratemonth   from Warehouse_store where date =( select max(date) from Warehouse_store where itemid = @ItemId and [type] = 'in' and avgrate != 0 ) and itemid = @ItemId and sid=@StoreId and [type] = 'in' ) End else if @ByDate = 1 begin select @AvgDate=(select distinct avgratemonth   from Warehouse_store where date =( select max(date) from Warehouse_store where itemid = @ItemId and [type] = 'in' and date <= @Date  ) and itemid = @ItemId and sid=@StoreId and [type] = 'in' ) End return @AvgDate End